"""Actual NMS publication evidence -> typed codec -> phone Root public chronometer/history backend."""
from pathlib import Path
import argparse
import runpy
import tempfile

BASE = runpy.run_path(str(Path(__file__).with_name("test-atomic-workbench-media-evidence.py")))
TEST = BASE["TEST"].split(" public static void main(String[] args)", 1)[0] + r'''
 static AtomicWorkbenchNotifications notifications(F f){return new AtomicWorkbenchNotifications(f.context,10,()->new Bundle(f.auth));}
 static void chrono(F f,String category,boolean down){f.notification.notification.category=category;f.notification.notification.when=System.currentTimeMillis()+(down?60000:-60000);f.notification.notification.extras.putBoolean(Notification.EXTRA_SHOW_CHRONOMETER,true);f.notification.notification.extras.putBoolean(Notification.EXTRA_CHRONOMETER_COUNT_DOWN,down);}
 static ArrayList<Bundle> cards(Bundle state){return state.getParcelableArrayList("cards",Bundle.class);}static Bundle card(Bundle state){return cards(state).get(0);}
 static Bundle recordRequest(Bundle card){Bundle b=new Bundle();b.putInt("schema",1);b.putString("request_id",String.format("%032x",++ids));b.putString("source_id",card.getString("source_id"));b.putString("source_generation",card.getString("source_generation"));b.putLong("source_revision",card.getLong("source_revision"));b.putLong("created_elapsed",SystemClock.now);b.putLong("deadline_elapsed",SystemClock.now+5000);return b;}
 public static void main(String[] args)throws Throwable{
  MediaBootstrap.install();
  test("actual published public countdown produces real signed time without body",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle s=n.state(),c=card(s);yes(s.getBoolean("success")&&c.getString("kind").equals("timer")&&c.getBoolean("time_known")&&c.getBoolean("can_record"),"real public countdown missing");yes(c.getLong("time_ms")>=59000&&c.getLong("time_ms")<=60100&&c.getBoolean("advancing"),"countdown not derived from actual public when");yes(!c.getBoolean("can_toggle")&&!c.getBoolean("can_stop")&&!c.getBoolean("can_lap")&&!s.getBoolean("recorder_available")&&!s.getBoolean("notification_actions_available"),"unknown source action enabled");yes(!c.keySet().contains("key")&&!c.keySet().contains("title")&&!c.keySet().contains("contentIntent")&&!c.keySet().contains("text"),"private notification body or key crossed UI contract");});
  test("public stopwatch category plus count-up is exact semantics",()->{F f=new F();chrono(f,"stopwatch",false);Bundle s=notifications(f).state();yes(card(s).getString("kind").equals("stopwatch")&&card(s).getLong("time_ms")>=59000&&!card(s).getBoolean("can_record")&&!card(s).getBoolean("can_lap"),"public stopwatch confused with local timer record");});
  for(String category:List.of("alarm","recording","service","transport","StopWatch","my.stopwatch.action"))test("uncertain semantics never guessed from category or numeric title: "+category,()->{F f=new F();chrono(f,category,false);f.notification.notification.extras.putString(Notification.EXTRA_TITLE,"倒计时 09:59 录音 秒表");Bundle s=notifications(f).state();yes(s.getBoolean("available")&&cards(s).isEmpty(),"guessed source type from text or fuzzy category");});
  test("numeric title alone does not invent a timer",()->{F f=new F();f.notification.notification.category="alarm";f.notification.notification.extras.putString(Notification.EXTRA_TITLE,"倒计时 10:00");yes(cards(notifications(f).state()).isEmpty(),"title text invented timer");});
  test("wrong typed public flag is unknown rather than truthy",()->{F f=new F();chrono(f,"alarm",true);f.notification.notification.extras.putString(Notification.EXTRA_SHOW_CHRONOMETER,"true");yes(cards(notifications(f).state()).isEmpty(),"wrong typed chronometer flag accepted");});
  test("same live generation updates keep source ID/history and do not create new event",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle first=n.state();Bundle stored=n.recordTimer(recordRequest(card(first)));yes(stored.getBoolean("record_stored")&&card(stored).getParcelableArrayList("records",Bundle.class).size()==1,"actual current timer sample not recorded");StatusBarNotification updated=notification(f.player);updated.notification.category="alarm";updated.notification.when=System.currentTimeMillis()+45000;updated.notification.extras.putBoolean(Notification.EXTRA_SHOW_CHRONOMETER,true);updated.notification.extras.putBoolean(Notification.EXTRA_CHRONOMETER_COUNT_DOWN,true);f.record=new NotificationRecord(updated);f.notification=updated;f.nms.publish(f.record);Bundle next=n.state();yes(card(first).getString("source_id").equals(card(next).getString("source_id"))&&first.getLong("event_revision")==next.getLong("event_revision")&&card(next).getLong("source_revision")>card(first).getLong("source_revision"),"ordinary notification update recreated page");yes(card(next).getParcelableArrayList("records",Bundle.class).size()==1,"update discarded real timer history");});
  test("local timer record is once-only and never invokes a source action",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle req=recordRequest(card(n.state()));Bundle first=n.recordTimer(req),duplicate=n.recordTimer(req);yes(first.getBoolean("record_stored")&&!duplicate.getBoolean("record_stored")&&card(n.state()).getParcelableArrayList("records",Bundle.class).size()==1,"duplicate local record admitted");yes(f.player.controls.total()==0&&f.player.controls.ratings==0,"timer record invoked media/source transport");});
  for(String bad:List.of("extra","type","stale_revision","stale_generation","ttl","future","deadline_during_query"))test("timer record metadata rejects "+bad,()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle req=recordRequest(card(n.state()));switch(bad){case "extra":req.putString("text","secret");break;case "type":req.putString("source_revision","1");break;case "stale_revision":req.putLong("source_revision",999);break;case "stale_generation":req.putString("source_generation","f".repeat(33));break;case "ttl":req.putLong("deadline_elapsed",SystemClock.now);break;case "future":req.putLong("created_elapsed",SystemClock.now+1);break;default:req.putLong("deadline_elapsed",11000);int base=ContentResolver.calls;ContentResolver.during=()->{if(ContentResolver.calls==base+2)SystemClock.now+=1500;};}Bundle r=n.recordTimer(req);yes(!r.getBoolean("record_stored")&&card(n.state()).getParcelableArrayList("records",Bundle.class).isEmpty(),"unsafe timer record admitted");});
  test("same-key remove/repost removes old history and renews page event",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle first=n.state();n.recordTimer(recordRequest(card(first)));f.repost();chrono(f,"alarm",true);Bundle next=n.state();yes(!card(first).getString("source_id").equals(card(next).getString("source_id"))&&next.getLong("event_revision")>first.getLong("event_revision")&&card(next).getParcelableArrayList("records",Bundle.class).isEmpty(),"new lifetime reused old page or history");});
  test("unknown temporary query keeps page/history but never advances or records",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle first=n.state();n.recordTimer(recordRequest(card(first)));ContentResolver.current=false;Bundle unavailable=n.state();yes(!unavailable.getBoolean("available")&&cards(unavailable).size()==1&&card(unavailable).getString("source_id").equals(card(first).getString("source_id"))&&!card(unavailable).getBoolean("time_known")&&!card(unavailable).getBoolean("advancing")&&!card(unavailable).getBoolean("can_record"),"unknown snapshot removed page or fabricated time");yes(card(unavailable).getParcelableArrayList("records",Bundle.class).size()==1,"unknown snapshot discarded confirmed history");ContentResolver.current=true;yes(card(n.state()).getBoolean("time_known"),"known state failed to recover");});
  test("same live source no longer exposes chronometer keeps page with unknown time",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle first=n.state();f.notification.notification.extras.putBoolean(Notification.EXTRA_SHOW_CHRONOMETER,false);Bundle next=n.state();yes(card(next).getString("source_id").equals(card(first).getString("source_id"))&&!card(next).getBoolean("time_known")&&!card(next).getBoolean("can_record"),"missing public clock guessed paused value or removed live source");});
  test("actual removed notification retires page and history only on confirmed snapshot",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);n.state();f.nms.remove(f.record);Bundle empty=n.state();yes(empty.getBoolean("success")&&cards(empty).isEmpty(),"ended source page persisted");});
  test("notification removed during final Provider fence is unknown not trusted empty",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle first=n.state();int base=ContentResolver.calls;ContentResolver.during=()->{if(ContentResolver.calls==base+2)synchronized(f.nms.mNotificationLock){f.nms.mNotificationsByKey.clear();}};Bundle next=n.state();yes(!next.getBoolean("success")&&cards(next).size()==1&&!card(next).getBoolean("time_known"),"raced NMS list was trusted");ContentResolver.during=null;yes(cards(n.state()).isEmpty(),"fresh empty failed to retire old page");});
  test("public chrono may expire below zero without self-finishing source notification",()->{F f=new F();chrono(f,"alarm",true);f.notification.notification.when=System.currentTimeMillis()-5000;Bundle s=notifications(f).state();yes(card(s).getBoolean("time_known")&&card(s).getLong("time_ms")<=-4900&&card(s).getBoolean("advancing"),"expired chrono invented completion/removal");});
  test("overflow and future stopwatch origins have unknown time",()->{F f=new F();chrono(f,"stopwatch",false);f.notification.notification.when=Long.MAX_VALUE;AtomicWorkbenchNotifications n=notifications(f);yes(!card(n.state()).getBoolean("time_known"),"future stopwatch invented elapsed value");f.notification.notification.when=0;yes(!card(n.state()).getBoolean("time_known"),"zero origin invented clock");});
  test("actual UID1000 clock in foreground user zero is not blanket-rejected",()->{F f=new F();ActivityManager.current=0;f.auth.putInt("uid",10555);f.auth.putInt("user",0);StatusBarNotification clock=new StatusBarNotification();clock.uid=1000;clock.user=0;clock.pkg="zte.com.cn.alarmclock";clock.key="system-clock";clock.notification.category="alarm";clock.notification.when=System.currentTimeMillis()+60000;clock.notification.extras.putBoolean(Notification.EXTRA_SHOW_CHRONOMETER,true);clock.notification.extras.putBoolean(Notification.EXTRA_CHRONOMETER_COUNT_DOWN,true);f.context.packages.overrides.put(clock.pkg,1000);f.nms.publish(new NotificationRecord(clock));AtomicWorkbenchNotifications n=new AtomicWorkbenchNotifications(f.context,0,()->new Bundle(f.auth));Bundle s=n.state();yes(s.getBoolean("success")&&cards(s).size()==1&&card(s).getInt("owner_uid")==1000&&card(s).getInt("user_id")==0,"valid system clock excluded by app UID threshold");});
  test("fresh package owner mismatch cannot create structured page",()->{F f=new F();chrono(f,"alarm",true);f.context.packages.overrides.put(f.player.pkg,1010777);yes(cards(notifications(f).state()).isEmpty(),"PM owner mismatch exposed notification page");});
  test("record bound is explicit and never silently evicts older samples",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);for(int i=0;i<32;i++)yes(n.recordTimer(recordRequest(card(n.state()))).getBoolean("record_stored"),"bounded sample not accepted");Bundle full=n.state();yes(card(full).getBoolean("records_full")&&!card(full).getBoolean("can_record")&&card(full).getParcelableArrayList("records",Bundle.class).size()==32,"history bound hidden or evicted old record");yes(!n.recordTimer(recordRequest(card(full))).getBoolean("record_stored"),"full history accepted extra sample");});
  test("new distinct event increments only once and is stable across snapshots",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle first=n.state();MediaController second=new MediaController(1010456,++ids,3,ALL);StatusBarNotification note=notification(second);note.notification.category="stopwatch";note.notification.when=System.currentTimeMillis()-1000;note.notification.extras.putBoolean(Notification.EXTRA_SHOW_CHRONOMETER,true);f.nms.publish(new NotificationRecord(note));Bundle both=n.state(),again=n.state();yes(cards(both).size()==2&&both.getLong("event_revision")>first.getLong("event_revision")&&again.getLong("event_revision")==both.getLong("event_revision"),"new event was missed or repeated");});
  test("close and user change remove retained page ownership",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);n.state();ActivityManager.current=11;yes(cards(n.state()).isEmpty(),"foreign foreground retained owned page");ActivityManager.current=10;n.state();n.close();yes(cards(n.state()).isEmpty()&&!n.state().getBoolean("available"),"closed backend retained live page");});
  test("user switch during rejected NMS query clears retained identities",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);n.state();ContentResolver.during=()->ActivityManager.current=11;Bundle s=n.state();yes(!s.getBoolean("success")&&cards(s).isEmpty(),"late foreground switch retained previous user source");});
  test("bounded raw NMS scan failure preserves old page with unverified time",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle old=n.state();for(int i=0;i<256;i++){StatusBarNotification note=notification(f.player);note.key="key-"+i;f.nms.publish(new NotificationRecord(note));}Bundle next=n.state();yes(!next.getBoolean("available")&&cards(next).size()==1&&!card(next).getBoolean("time_known")&&card(next).getString("source_id").equals(card(old).getString("source_id")),"partial NMS scan falsely retired or advanced old source");});
  test("wall clock jump invalidates even first read until source actually republishes",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);SystemClock.now+=3600000;Bundle jumped=n.state();yes(cards(jumped).size()==1&&!card(jumped).getBoolean("time_known")&&card(jumped).getString("time_status").equals("clock_changed"),"first read fabricated origin after wall-clock jump");StatusBarNotification updated=notification(f.player);updated.notification.category="alarm";updated.notification.when=System.currentTimeMillis()+60000;updated.notification.extras.putBoolean(Notification.EXTRA_SHOW_CHRONOMETER,true);updated.notification.extras.putBoolean(Notification.EXTRA_CHRONOMETER_COUNT_DOWN,true);f.nms.publish(new NotificationRecord(updated));yes(card(n.state()).getBoolean("time_known"),"actual source republish did not reestablish clock evidence");});
  test("unwitnessed pre-hook publication never invents a monotonic clock origin",()->{F f=new F();chrono(f,"alarm",true);StatusBarNotification untracked=notification(f.player);untracked.notification=f.notification.notification;f.nms.mNotificationsByKey.put(untracked.getKey(),new NotificationRecord(untracked));Bundle s=notifications(f).state();yes(cards(s).size()==1&&!card(s).getBoolean("time_known")&&!card(s).getBoolean("can_record"),"unwitnessed notification invented timer origin");});
  test("same revision projects from witnessed publication origin and exposes bounded precision",()->{F f=new F();chrono(f,"alarm",true);AtomicWorkbenchNotifications n=notifications(f);Bundle first=card(n.state());SystemClock.now+=100;Bundle next=card(n.state());yes(first.getLong("time_ms")-next.getLong("time_ms")==100,"poll recomputed timer instead of retaining monotonic origin");yes(next.getInt("display_resolution_ms")==1000&&next.getLong("valid_until_elapsed")==SystemClock.now+2000,"public seconds resolution or freshness bound missing");});
  System.out.println("NOTIFICATION CHRONOMETER RESULT "+cases+" cases; "+checks+" assertions");
 }
}'''


def main():
    parser = argparse.ArgumentParser(description=__doc__); parser.add_argument("--negative-controls", action="store_true"); args = parser.parse_args()
    BASE["run"].__globals__["TEST"] = TEST
    with tempfile.TemporaryDirectory(prefix="duo-notification-chrono-") as directory:
        result = BASE["run"](Path(directory)); print(result.stdout, end="")
        if result.returncode: raise AssertionError(result.stderr)
    if not args.negative_controls: return
    mutations = [
        ("AtomicWorkbenchNotificationRecord", 'if (!showChronometer) return "";', '// MUTANT ignore typed public clock', "wrong typed chronometer flag accepted"),
        ("AtomicWorkbenchNotifications", 'old.record.sameLifetime(record)', 'true', "new lifetime reused old page or history"),
        ("AtomicWorkbenchNotifications", 'seen.containsKey(request.getString("request_id"))', 'false', "duplicate local record admitted"),
        ("AtomicWorkbenchNotifications", 'target.record.revision != request.getLong("source_revision")', 'false', "unsafe timer record admitted"),
        ("AtomicWorkbenchNotifications", 'if (fresh == null || !source.originKnown', 'if (fresh == null) return new Time(0, 0); if (!source.originKnown', "unknown snapshot removed page or fabricated time"),
        ("AtomicWorkbenchNotifications", 'next.publishedClockKnown && (drift > 250 || drift < -250)', 'false', "first read fabricated origin after wall-clock jump"),
        ("AtomicWorkbenchNotifications", 'originKnown = next.publishedClockKnown && next.when > 0 && next.showChronometer;', 'originKnown = next.when > 0 && next.showChronometer;', "unwitnessed notification invented timer origin"),
    ]
    for mutation in mutations:
        with tempfile.TemporaryDirectory(prefix="duo-notification-chrono-negative-") as directory:
            result = BASE["run"](Path(directory), mutation)
            if result.returncode == 0 or mutation[3] not in result.stdout + result.stderr: raise AssertionError(result.stdout + result.stderr)
            print("PASS notification chrono negative control: " + mutation[3])


if __name__ == "__main__": main()
